const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const borGeometry = ee.Geometry.Point([31.5599, 6.2065]).buffer(50000); // 50km buffer around Bor

  const date2019 = ee.Date('2019-12-06');
  const date2021 = ee.Date('2021-12-04');

  // 2. Data Acquisition - Sentinel-2 for water detection
  function getS2Collection(date, bufferDays = 5) {
    const startDate = date.advance(-bufferDays, 'day');
    const endDate = date.advance(bufferDays, 'day');

    return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(borGeometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
  }

  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  function calculateNDWI(image) {
    return image.normalizedDifference(['B3', 'B8']).rename('NDWI');
  }

  // Get collections for both dates
  const col2019 = getS2Collection(date2019);
  const col2021 = getS2Collection(date2021);

  // Check if collections are empty
  const count2019 = col2019.size().getInfo();
  const count2021 = col2021.size().getInfo();

  console.log(`2019-12-06 Images: ${count2019}`);
  console.log(`2021-12-04 Images: ${count2021}`);

  if (count2019 === 0 || count2021 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get best image (least cloudy) for each date
  const img2019 = col2019.sort('CLOUDY_PIXEL_PERCENTAGE').first();
  const img2021 = col2021.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // Process images: cloud mask and calculate NDWI
  const ndwi2019 = calculateNDWI(maskClouds(img2019));
  const ndwi2021 = calculateNDWI(maskClouds(img2021));

  // Create water mask (NDWI > 0.0 for water)
  const water2019 = ndwi2019.gt(0.0);
  const water2021 = ndwi2021.gt(0.0);

  // Count water pixels
  const waterCount2019 = water2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: borGeometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const waterCount2021 = water2021.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: borGeometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  // Count total valid pixels to check if we have data
  const totalPixels2019 = water2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: borGeometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const totalPixels2021 = water2021.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: borGeometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`2019 Water Pixels: ${waterCount2019}, Total: ${totalPixels2019}`);
  console.log(`2021 Water Pixels: ${waterCount2021}, Total: ${totalPixels2021}`);

  // Check for no valid pixels
  if (totalPixels2019 === 0 || totalPixels2021 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (waterCount2019 === null || waterCount2021 === null || 
      isNaN(waterCount2019) || isNaN(waterCount2021)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare water extent
  console.log(`Water Extent Ratio (2021/2019): ${(waterCount2021/waterCount2019).toFixed(2)}`);

  if (waterCount2021 > waterCount2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
